prompt --application/pages/page_00001
begin
wwv_flow_imp_page.create_page(
 p_id=>1
,p_name=>'AI and Maps'
,p_alias=>'AI-AND-MAPS'
,p_step_title=>'Forest AI and Maps'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function () {',
'  "use strict";',
'  const $ = apex.jQuery;',
'  let busy = false;',
'  let started = false;',
'  let mapPending = false;',
'  let mapLoading = false;',
'  function mapNote(message) {',
'    if (!document.getElementById("nai-map-note")) {',
'      $("<p>", {id: "nai-map-note", "class": "nai-note", role: "status"}).insertAfter("#nai-status");',
'    }',
'    $("#nai-map-note").text(message);',
'  }',
'  function syncMap() {',
'    if (!mapPending || mapLoading) return;',
'    const region = apex.region("NAI_MAP");',
'    // The native map is loaded asynchronously; the basic region interface',
'    // can exist before its map methods and MapLibre instance are available.',
'    const map = region && typeof region.getMapObject === "function" ? region.getMapObject() : null;',
'    if (!map || (typeof map.isStyleLoaded === "function" && !map.isStyleLoaded())) {',
'      mapNote("The map is still loading. You can continue the conversation while it loads.");',
'      return;',
'    }',
'    mapPending = false;',
'    mapLoading = true;',
'    function failed(err) {',
'      mapNote("The response was received, but the map could not be updated: " + (err && err.message ? err.message : String(err)));',
'      apex.debug.warn("NIBIO map refresh:", err);',
'    }',
'    function finished() {',
'      mapLoading = false;',
'      if (mapPending) syncMap();',
'    }',
'    try {',
unistr('      mapNote("Loading map geometries \2026");'),
'      // reset() reuses preloaded mapData when lazyLoading=false. Refresh',
'      // fetches the new collection contents; only then use the new bounds.',
'      const loading = region.refresh();',
'      if (!loading || typeof loading.then !== "function") {',
'        throw new Error("The map refresh could not be started.");',
'      }',
'      Promise.resolve(loading).then(function () {',
'        if (mapPending) return;',
'        const data = region.mapData;',
'        const bbox = data && data.map && data.map.bbox;',
'        if (Array.isArray(bbox) && bbox.length === 4 && bbox.every(Number.isFinite)) {',
'          map.fitBounds([[bbox[0], bbox[1]], [bbox[2], bbox[3]]], {padding: 36, maxZoom: 16});',
'        }',
'        mapNote("");',
'      }).catch(failed).finally(finished);',
'    } catch (err) {',
'      failed(err);',
'      finished();',
'    }',
'  }',
'  function mode() {',
'    const agent = apex.item("P1_MODE").getValue() === "AGENT";',
'    $("#P1_TEAM_CONTAINER").toggle(agent);',
'    $("#P1_PROFILE_CONTAINER,#P1_ACTION_CONTAINER").toggle(!agent);',
'    $("#nai-mode-note").text(agent',
'      ? "The team uses its own AI profiles and tools. For the forest team, map geometries are retrieved from NF_STAND."',
'      : "SQL results and the map display up to 200 rows. SDO_GEOMETRY is displayed directly; forest results with STAND_ID use geometries from NF_STAND.");',
'  }',
'  function error(message) {',
'    apex.message.clearErrors();',
'    apex.message.showErrors([{type: "error", location: "page", message: message, unsafe: false}]);',
'  }',
'  function request(operation) {',
'    if (busy) return;',
'    if (operation === "SEND" && !String(apex.item("P1_PROMPT").getValue() || "").trim()) {',
'      error("Enter a question first."); return;',
'    }',
'    busy = true;',
'    apex.message.clearErrors();',
'    $("#nai-send,#nai-new").prop("disabled", true);',
unistr('    $("#nai-status").text(operation === "SEND" ? "Getting a response \2026" : "Preparing the conversation \2026");'),
'    const spinner = apex.util.showSpinner($("#nai-history"));',
'    let finished = false;',
'    function finish() {',
'      if (finished) return;',
'      finished = true;',
'      busy = false;',
'      spinner.remove();',
'      $("#nai-send,#nai-new").prop("disabled", false);',
'    }',
'    try {',
'      apex.server.process("NAI_API", {',
'      x01: operation,',
'      pageItems: "#P1_MODE,#P1_PROFILE,#P1_TEAM,#P1_ACTION,#P1_PROMPT"',
'    }, {',
'      dataType: "json",',
'      success: function (data) {',
'        try {',
'        if (!data || typeof data.ok !== "boolean") {',
'          error("The server returned an unexpected response. Reload the page and sign in again if necessary.");',
'          return;',
'        }',
'        if (!data.ok) {',
'          error(data.message || data.error || "The response could not be retrieved.");',
'          $("#nai-status").text("An error occurred. You can try again.");',
'          return;',
'        }',
'        $("#nai-conversation").text(data.conversation_id || "Created when you ask your first question");',
'        // HTML is rendered by the server, with escaping of all AI and database values.',
'        $("#nai-history").html(data.history_html);',
'        $("#nai-status").text(data.map_count + " geometries in the latest response");',
'        // Initial map data is loaded by APEX itself. Refresh only when a',
'        // request has changed the result; defer it if the map is not ready.',
'        if (operation !== "INIT") mapPending = true;',
'        syncMap();',
'        if (operation === "SEND") {',
'          apex.item("P1_PROMPT").setValue("");',
'          const log = document.getElementById("nai-history");',
'          log.scrollTop = log.scrollHeight;',
'        }',
'        } catch (err) {',
'          error("The response was received, but the display could not be updated: " + err.message);',
'          apex.debug.warn("NIBIO response display:", err);',
'        } finally {',
'          // A rendering or map error must never leave Send disabled.',
'          finish();',
'        }',
'      },',
'      error: function (xhr, status, detail) {',
'        try {',
'          if (status === "APEX") {',
'            const message = typeof detail === "string" ? detail',
'              : detail && typeof detail.message === "string" ? detail.message : "Unknown server error.";',
'            error("The server returned an error: " + message);',
'            $("#nai-status").text("A server error occurred. You can try again.");',
'            return;',
'          } else if (xhr && xhr.status === 401) {',
'            error("The server rejected the sign-in (HTTP 401). Reload the page and sign in to APEX again.");',
'          } else if (xhr && xhr.status === 403) {',
'            error("The server denied access to the application request (HTTP 403). Check your APEX sign-in and application access.");',
'          } else {',
'            error("The request was interrupted or failed. If it timed out, the AI request may still be running in the database. Reload the page to check for a saved response before sending again.");',
'          }',
'          $("#nai-status").text("No confirmed response (" + (xhr && xhr.status ? "HTTP " + xhr.status + ", " : "") + status + ").");',
'        } finally {',
'          finish();',
'        }',
'      },',
'      complete: finish',
'    });',
'    } catch (err) {',
'      finish();',
'      error("The request could not be started: " + err.message);',
'    }',
'  }',
'  function start() {',
'    if (started) return;',
'    started = true;',
'    mode();',
'    $("#P1_MODE").on("change", mode);',
'    $("#P1_MODE,#P1_PROFILE,#P1_TEAM,#P1_ACTION").on("change", function () {',
'      $("#nai-status").text("The selection has changed. Your next question will start a new conversation.");',
'    });',
'    $("#nai-send").on("click", function (e) {e.preventDefault(); request("SEND");});',
'    $("#nai-new").on("click", function (e) {e.preventDefault(); request("NEW");});',
'    $("#P1_PROMPT").on("keydown", function (e) {',
'      if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) {e.preventDefault(); request("SEND");}',
'    });',
'    request("INIT");',
'  }',
'  $(apex.gPageContext$).on("spatialmapinitialized.naiAI", "#NAI_MAP", syncMap);',
'  // Wait for APEX item initialization as well as the DOM.',
'  $(apex.gPageContext$).one("apexreadyend.naiAI", start);',
'})();',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
':root { --nai-green: #245d42; }',
'.nai-intro { color: #496152; max-width: 78ch; }',
