'.nai-table th { background: #edf4ef; position: sticky; top: 0; }',
'.nai-meta { font-size: .8rem; overflow-wrap: anywhere; margin-top: .75rem; color: #53665b; }',
'#nai-status { min-height: 1.5em; }',
''))
